// Some portions generated by Claude
import assert from "node:assert/strict";
import test from "node:test";
import { filterChipGroups } from "../../../main/frontend/graph-explorer/filter-chips.ts";

// The active filters as pills: one per value, grouped per filter, with "or" (any of the values) or "and" (all of them)
// between the values of a filter.
const chip = (facetId, facetLabel, valueId, text) => ({ facetId, facetLabel, valueId, text });

test("pills are grouped per filter in their order, each group saying how its values combine", () => {
  const groups = filterChipGroups(
    [
      chip("__rdf_type__", "Type", "urn:Person", "Person"),
      chip("__rdf_type__", "Type", "urn:Droid", "Droid"),
      chip("urn:character", "character", "urn:luke", "character: Luke"),
      chip("urn:character", "character", "urn:leia", "character: Leia"),
      chip("urn:age", "age", null, "age: 30 – 40"),
    ],
    new Map([["urn:character", "all"]]),
  );
  assert.deepEqual(
    groups.map((group) => [group.facetId, group.mode, group.joiner, group.label, group.chips.map((item) => item.text)]),
    [
      ["__rdf_type__", "any", "or", "Type, any of", ["Person", "Droid"]],
      ["urn:character", "all", "and", "character, all of", ["character: Luke", "character: Leia"]],
      ["urn:age", "any", null, "age", ["age: 30 – 40"]],
    ],
  );
});

test("a filter with one value has no joiner, whatever its mode", () => {
  const [group] = filterChipGroups([chip("urn:character", "character", "urn:luke", "character: Luke")], new Map([["urn:character", "all"]]));
  assert.equal(group.joiner, null);
  assert.equal(group.label, "character");
});

test("no filters, no groups", () => {
  assert.deepEqual(filterChipGroups([], new Map()), []);
});
